solutionCode:
def sort_ascending(values):
    ordered = []
    for value in values:
        ordered.append(value)
    for start in range(len(ordered)):
        best = start
        for index in range(start + 1, len(ordered)):
            if ordered[index] < ordered[best]:
                best = index
        carried = ordered[start]
        ordered[start] = ordered[best]
        ordered[best] = carried
    return ordered

